export const moduleCatalog = [
 {id:'distance',name:'Ultrasonik mesafe sensörü',evidence:'Fotoğrafta görülen çift dönüştürücülü modül',purpose:'Patikadaki nesne uzaklığını ve depo seviyesini gözlemle.',focus:[-2.05,.3,2.7],kind:'range',label:'Nesne uzaklığı',min:5,max:150,value:80,unit:'cm'},
 {id:'pir',name:'PIR hareket sensörü',evidence:'Fotoğraftaki beyaz kubbeli yeşil modül',purpose:'Canlı geçişlerinde hareket olayını gözlemle. Tür veya kişi tanımaz.',focus:[.15,.3,2.7],kind:'event',label:'Hareket oluştur'},
 {id:'rfid',name:'RFID-RC522 okuyucu',evidence:'Fotoğrafta kart üzerindeki model yazısı okunuyor',purpose:'Araştırma istasyonuna kartla giriş olayını canlandır.',focus:[1.15,.2,2.7],kind:'event',label:'Kartı yaklaştır'},
 {id:'ir',name:'Kızılötesi alıcı',evidence:'Fotoğraftaki küçük siyah modül; model numarası doğrulanmadı',purpose:'Kumandadan gelen bir kontrol olayını canlandır.',focus:[-2,.2,-2.35],kind:'event',label:'Kumanda sinyali gönder'},
 {id:'red-module',name:'Kırmızı sensör modülü',evidence:'Fotoğrafta görünüyor; işlev ve model kesinleşmedi',purpose:'Kart, ayar trimeri ve bağlantı uçlarını incele. Model doğrulanmadan ölçüm üretilmez.',focus:[-.85,.2,-2.35],kind:'inspect'},
 {id:'light',name:'LDR ışık sensörü',evidence:'Kutu şemasında gösteriliyor; bağımsız parça yakın çekimde doğrulanmadı',purpose:'Yaprak gölgesiyle aydınlık değişimini karşılaştır. Çizim çalışma prensibini temsil eder.',focus:[.3,.3,-2.35],kind:'range',label:'Göreli ışık',min:0,max:100,value:62,unit:'%'},
 {id:'climate',name:'Sıcaklık / nem sensörü',evidence:'Kutu şemasında gösteriliyor; gerçek modül tipi doğrulanmadı',purpose:'Fidanlık mikroiklimini incele. Çizim ve değerler eğitim örneğidir.',focus:[1.45,.3,-2.35],kind:'range',label:'Örnek sıcaklık',min:5,max:45,value:24,unit:'°C'},
 {id:'servo',name:'Mikro servo motor',evidence:'Fotoğraftaki mavi gövdeli, beyaz kollu motor',purpose:'Bir sera kapağının açısını ayarla. Servo bir hareket elemanıdır.',focus:[-.85,.3,2.7],kind:'range',label:'Kol açısı',min:0,max:180,value:90,unit:'°'}
];
export function mountModuleLibrary(root, api){
 let cache={};try{cache=JSON.parse(localStorage.getItem('canopy-module-library')||'{}')||{};}catch{}
 let selected='distance',mission,added=new Set(),required=new Set();
 const q=s=>root.querySelector(s);const all=s=>[...root.querySelectorAll(s)];
 root.innerHTML=`<div class="module-heading"><div><span>FOTOĞRAFLARINDAN PARÇA KÜTÜPHANESİ</span><h3>Görev masanı genişlet</h3><p>Bir sensörü ekle, yakından incele ve tepkisini dene.</p></div><button class="secondary" id="moduleOverview">Masayı göster</button></div><div id="moduleCards" class="module-cards"></div><div class="module-preview-row"><div class="module-preview-wrap"><canvas id="modulePreview" aria-label="Seçili sensörün canlı 3B önizlemesi" tabindex="0"></canvas><span>Parçayı sürükleyerek döndür</span></div><div id="moduleExperiment" class="module-experiment"></div></div><p class="module-note">Ek parça deneyleri görev kodundan bağımsızdır; görev puanını değiştirmez. Fiziksel bağlantı ve ölçüm yerine eğitim gösterimi sunar.</p><output id="moduleAnnouncement" role="status" aria-live="polite"></output>`;
 api.preview(q('#modulePreview'));
 const save=()=>{cache[mission.id]=[...added];try{localStorage.setItem('canopy-module-library',JSON.stringify(cache));}catch{}api.modules([...new Set([...added,...required])]);};
 function experiment(){const m=moduleCatalog.find(x=>x.id===selected),on=added.has(m.id)||required.has(m.id);q('#moduleExperiment').innerHTML=`<div><span class="module-evidence">${m.evidence}</span><h4>${m.name}</h4><p>${m.purpose}</p></div><div class="module-controls">${!on?'<p>Denemek için parçayı sahneye ekle.</p>':m.kind==='range'?`<label>${m.label}<input id="moduleInput" type="range" min="${m.min}" max="${m.max}" value="${api.value(m.id)??m.value}"><output id="moduleValue">${api.value(m.id)??m.value} ${m.unit}</output></label>`:m.kind==='event'?`<button class="primary" id="moduleTrigger">${m.label}</button><output id="moduleEventResult" role="status">Sinyal bekleniyor</output>`:'<p>Modeli döndürerek görsel ayrıntılarını inceleyebilirsin.</p>'}${on?'<button class="secondary" id="moduleFocus">Parçaya yakınlaş</button>':''}</div>`;
 api.previewSelect(m.id,m.focus);
 q('#moduleInput')?.addEventListener('input',e=>{const value=Number(e.target.value);q('#moduleValue').textContent=value+' '+m.unit;api.input(m.id,value);});q('#moduleTrigger')?.addEventListener('click',()=>{api.trigger(m.id);q('#moduleEventResult').textContent={pir:'Hareket olayı algılandı',rfid:'Örnek kart okundu',ir:'Örnek kumanda sinyali alındı'}[m.id];});q('#moduleFocus')?.addEventListener('click',()=>api.focus(m.focus));}
 function render(){q('#moduleCards').innerHTML=moduleCatalog.map(m=>{const on=added.has(m.id)||required.has(m.id);return `<article class="module-card ${on?'is-added':''}"><button class="module-select" data-module-select="${m.id}" aria-pressed="${selected===m.id}"><span>${m.id==='servo'?'HAREKET ELEMANI':m.id==='red-module'?'KİMLİĞİ DOĞRULANACAK':'SENSÖR'}</span><strong>${m.name}</strong></button><button class="module-add" data-module-add="${m.id}" aria-pressed="${on}" ${required.has(m.id)?'disabled':''}>${required.has(m.id)?'Görevde gerekli':on?'Sahneden kaldır':'Sahneye ekle'}</button></article>`;}).join('');all('[data-module-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.moduleSelect;render();});all('[data-module-add]').forEach(b=>b.onclick=()=>{const id=b.dataset.moduleAdd;selected=id;if(added.has(id))added.delete(id);else added.add(id);save();render();q('#moduleAnnouncement').textContent=moduleCatalog.find(m=>m.id===id).name+(added.has(id)?' sahneye eklendi.':' sahneden kaldırıldı.');});experiment();}
 function refresh(){mission=api.mission();required=new Set(mission.connections.some(pair=>pair.includes('TRIG'))?['distance']:[]);added=new Set(Array.isArray(cache[mission.id])?cache[mission.id].filter(id=>moduleCatalog.some(m=>m.id===id)):[]);save();render();}
 q('#moduleOverview').onclick=()=>api.focus(null);document.addEventListener('canopy-mission',refresh);refresh();
}
